def top_word(words):
    freq = {}
    for w in words:
        freq[w] = freq.get(w, 0) + 1
    best = None
    for w in sorted(freq):
        if best is None or freq[w] > freq[best]:
            best = w
    return best


def main():
    lines = read_lines()
    words = lines[1].split()
    print(top_word(words))


