def two_sum(nums, target):
    seen = {}
    for j, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], j]
        if x not in seen:
            seen[x] = j
    return [-1, -1]


def main():
    lines = read_lines()
    nums = list(map(int, lines[1].split()))
    target = int(lines[2])
    print(' '.join(map(str, two_sum(nums, target))))


