def anagram_groups(words):
    groups = {}
    for w in words:
        key = "".join(sorted(w))
        groups[key] = groups.get(key, 0) + 1
    return sorted(groups.values(), reverse=True)


def main():
    lines = read_lines()
    words = lines[1].split()
    sizes = anagram_groups(words)
    print(len(sizes))
    print(' '.join(map(str, sizes)))


