import sys


def read_lines():
    return [ln.strip() for ln in sys.stdin.read().split('\n') if ln.strip() != '']


def longest_unique(s):
    last = {}
    start = 0
    best = 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        if i - start + 1 > best:
            best = i - start + 1
    return best


def main():
    lines = read_lines()
    print(longest_unique(lines[0]))


